window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b645eab3aee47ea8"]={"versions": [{"id": "FIG-b645eab3aee47ea8", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML / MSR-FIBEX-Kompatibilität).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R3.0.7 / R3.1.5).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung des Kommunikations-Metamodells in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Signal-Definitionen auf VFB-/Softwarekomponenten-Ebene (<code>SystemSignal</code>, <code>SystemSignalGroup</code>).</li>\n<li><strong>Interaction & Network Layer:</strong> Netzwerk- und PDU-Abstraktion (COM-Stack, PduR, NM, DCM; Signal-zu-PDU-Serialisierung, PDU-Typisierung, PDU-Gruppen, ECU-Instanz-Zuordnung).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (Bus-Frames, PDU-zu-Frame-Verschachtelung, Timing-Vorgaben sowie Frame-/PDU-/Signal-Triggering auf <code>PhysicalChannel</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Formale Beschreibung des Signal- und PDU-Flusses vom anwendungsnahen Signal über die PDU-Kapselung bis zur physikalischen Übertragung im Kommunikationsnetzwerk (CAN, LIN, FlexRay). Bildet die autoritative Eingangsbasis für AUTOSAR-System- und ECU-Generatoren (z. B. Generierung von Com-, PduR- und Bus-Interface-Konfigurationen).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>AbstractSignal</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Abstrakter Vorgänger für anwendungsbezogene Signale.</li>\n<li><strong><code>SystemSignal</code></strong> <em>(Spezialisierung von <code>AbstractSignal</code>)</em>:</li>\n<li>Repräsentiert das anwendungsnahe Datum / Signal.</li>\n<li>Attribut: <code>+ length: Int</code> (Signalbreite in Bits).</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Spezialisierung von <code>AbstractSignal</code>)</em>:</li>\n<li>Aggregation zusammengehöriger atomarer Signale zur Gewährleistung von Signal-Konsistenz.</li>\n<li>Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal (Repräsentant des <code>SystemSignal</code> im Kommunikations-Stack).</li>\n<li>Assoziation: <code>+systemSignal 1</code> $\\rightarrow$ <code>AbstractSignal</code> (Kardinalität <code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Definiert das Packing/Serialisieren eines <code>ISignal</code> in eine <code>SignalIPdu</code>.</li>\n<li>Attribute:</li>\n<li><code>+ packingByteOrder: ByteOrderEnum</code> (Endianness: <code>MOST-SIGNIFICANT-BYTE-FIRST</code> / <code>LEAST-SIGNIFICANT-BYTE-FIRST</code>).</li>\n<li><code>+ startPosition: Int [0..1]</code> (Bit-Offset innerhalb der PDU).</li>\n<li><code>+ transferProperty: TransferPropertyEnum</code> (z. B. <code>TRIGGERED</code>, <code>PENDING</code>, <code>TRIGGERED_ON_CHANGE</code>).</li>\n<li><code>+ updateIndicationBitPosition: Int [0..1]</code> (Position des Update-Bits zur Validierung neuer Nutzdaten).</li>\n<li>Assoziationen:</li>\n<li>Referenziert <code>+signal 1</code> $\\rightarrow$ <code>ISignal</code> (Kardinalität <code>1..*</code> an Mapping).</li>\n<li>Komposition durch <code>SignalIPdu</code> via <code>+signalToPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Interaktions-PDU (Basis für COM/PduR-Verarbeitung).</li>\n<li>Attribute:</li>\n<li><code>+ length: Int</code> (Länge in Bytes).</li>\n<li><code>+ unusedBitPattern: Int [0..1]</code> (Auffüllmuster für ungenutzte Bits).</li>\n<li>Spezialisierungen von <code>IPdu</code>:</li>\n<li><strong><code>SignalIPdu</code></strong>: Standard-PDU des AUTOSAR COM, enthält <code>ISignalToIPduMapping</code> (<code>0..*</code>).</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Unterstützt PDU-Multiplexing über dynamische Selektoren.</li>\n<li>Attribute: <code>+ selectorFieldByteOrder: ByteOrderEnum</code>, <code>+ selectorFieldLength: Int</code>, <code>+ selectorFieldStartPosition: Int</code>, <code>+ triggerMode: TriggerMode</code>.</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU für UDS/KWP-Kommunikation via DCM.</li>\n<li><strong><code>NPdu</code></strong>: Transport-Layer-PDU (z. B. für CanTp / FrTp Segmentierung).</li>\n<li><strong><code>NmPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Netzwerkmanagement-PDU (Autosar NM).</li>\n<li>Attribute:</li>\n<li><code>+ length: Int</code></li>\n<li><code>+ nmCbvPosition: Int [0..1]</code> (Position des Control Bit Vector).</li>\n<li><code>+ nmNidPosition: Int [0..1]</code> (Position der Node Identifier).</li>\n<li><code>+ nmUserDataLength: Int [0..1]</code> (Länge der nutzbaren NM-Nutzdaten).</li>\n<li><strong><code>IPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Gruppiert IPdus für gemeinsame Steuerung (Start/Stop via COM API).</li>\n<li>Attribute:</li>\n<li><code>+ communicationDirection: communicationDirectionType</code> (<code>IN</code> / <code>OUT</code>).</li>\n<li><code>+ communicationMode: String</code>.</li>\n<li>Assoziationen:</li>\n<li>Rekursive Aggregation: <code>+containedIPduGroups 0..*</code> (Hierarchie von PDU-Gruppen).</li>\n<li>Referenz auf <code>SignalIPdu</code>: <code>+iPdu 0..<em></code> (Kardinalität <code>1..</em></code> an <code>IPduGroup</code>).</li>\n<li><strong><code>CoreTopology::EcuInstance</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Repräsentation des Steuergeräts im Netzwerk.</li>\n<li>Attribute:</li>\n<li><code>+ comConfigurationId: Int [0..1]</code>, <code>+ comProcessingPeriod: Float</code> (zyklischer COM-Task-Tick).</li>\n<li><code>+ diagnosticAddress: Int [0..1]</code>, <code>+ pduRConfigurationId: Int [0..1]</code>.</li>\n<li><code>+ responseAddress: Int [0..*]</code>, <code>+ sleepModeSupported: Boolean</code>, <code>+ wakeUpOverBusSupported: Boolean</code>.</li>\n<li>Assoziation: <code>1</code> $\\rightarrow$ <code>+associatedIPduGroup *</code> (Zuordnung konfigurierter PDU-Gruppen zu einer ECU).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Busspezifischer physikalischer Datenrahmen (CAN-Message, FlexRay-Frame, LIN-Frame).</li>\n<li>Attribut: <code>+ frameLength: Int</code> (Länge in Bytes, z. B. max. 8 Byte für Classic CAN, 64 Byte für FlexRay/CAN FD).</li>\n<li>Komposition: Enthält <code>+pduToFrameMapping 0..*</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotypen <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Platziert PDUs in Frames (Mehrfachkapselung / PDU-Container / Gateways).</li>\n<li>Attribute:</li>\n<li><code>+ packingByteOrder: ByteOrderEnum</code>.</li>\n<li><code>+ startPosition: Int</code> (Bit-Offset des PDU-Payloads im Frame).</li>\n<li><code>+ updateIndicationBitPosition: Int [0..1]</code>.</li>\n<li>Assoziation: <code>+pdu 1</code> $\\rightarrow$ <code>Pdu</code> (Kardinalität <code>1..*</code> an Mapping).</li>\n<li><strong><code>IPduTiming</code></strong>:</li>\n<li>Timing-Anforderungen für die PDU-Aussendung auf dem Bus.</li>\n<li>Attribut: <code>+ minimumDelay: Float [0..1]</code> (Mindestabstand zwischen zwei Sendevorgängen / Transmission Deadline Monitoring / MinDelayTimer).</li>\n<li>Assoziation: <code>+timingRequirement 0..1</code> $\\rightarrow$ <code>IPduTriggering</code>.</li>\n<li><strong>Triggering-Klassen auf dem physischen Kanal:</strong></li>\n<li><strong><code>CoreTopology::PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>: Physischer Kommunikationskanal (z. B. CAN-Cluster-Kanal). Besitzt per Komposition mit Stereotyp <code>«splitable»</code>:</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+iPduTriggering 0..*</code> $\\rightarrow$ <code>IPduTriggering</code>.</li>\n<li><code>+frameTriggerings 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>: Verknüpft <code>ISignal</code> (<code>+signal 1</code>) mit dem Kanal.</li>\n<li><strong><code>IPduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>: Verknüpft <code>IPdu</code> (<code>+iPdu 1</code>) mit dem Kanal. Assoziiert mit <code>+iSignalTriggering 0..*</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>: Ordnet den <code>Frame</code> (<code>+frame 1</code>) dem Kanal zu (definiert Bus-ID, Frame-ID, Slot). Assoziiert mit <code>+iPduTriggering 0..*</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-f8c73236c26d0564", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML / MSR-FIBEX-Kompatibilität).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R3.2.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung des Kommunikations-Metamodells in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Signal-Definitionen auf VFB-/Softwarekomponenten-Ebene (<code>SystemSignal</code>, <code>SystemSignalGroup</code>, abgeleitet von <code>AbstractSignal</code>).</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, PduR, NM, DCM; Signal-zu-PDU-Serialisierung, PDU-Typisierung inklusive anwenderspezifischer PDUs wie <code>UserDefinedPdu</code>/<code>UserDefinedIPdu</code>, PDU-Gruppierung via <code>IPduGroup</code> und <code>PdurIPduGroup</code>, ECU-Instanz-Zuordnung).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (Bus-Frames, PDU-zu-Frame-Verschachtelung via <code>PduToFrameMapping</code>, Timing-Vorgaben via <code>IPduTiming</code> sowie Frame-, PDU- und Signal-Triggering auf <code>PhysicalChannel</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der Signal- und PDU-Transformationen von Anwendungssignalen über PDU-Strukturen bis zur deterministischen Busübertragung auf physischen Kanälen (CAN, LIN, FlexRay).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>AbstractSignal</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Abstrakter Vorgänger für anwendungsbezogene Signale.</li>\n<li><strong><code>SystemSignal</code></strong> <em>(Spezialisierung von <code>AbstractSignal</code>)</em>:</li>\n<li>Repräsentiert das anwendungsnahe Datum/Signal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Spezialisierung von <code>AbstractSignal</code>)</em>:</li>\n<li>Aggregation zusammengehöriger atomarer Signale: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Signal-Repräsentant im Kommunikations-Stack; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>AbstractSignal</code> (<code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Definiert das Mapping eines <code>ISignal</code> in eine PDU.</li>\n<li>Referenziert <code>+signal 1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..*</code> am Mapping).</li>\n<li>Enthalten via Komposition <code>+signalToPduMapping 0..<em></code> in <code>SignalIPdu</code> sowie via Komposition <code>+iSignalToIPduMapping 0..</em></code> in <code>NmPdu</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU, enthält <code>ISignalToIPduMapping</code> (<code>0..*</code>).</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Generische nutzerdefinierte PDU außerhalb des standardisierten Kommunikations-Stacks.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>SignalIPdu</code></strong>: Enthält Signale via <code>ISignalToIPduMapping</code> (<code>0..*</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU für den Diagnostic Communication Manager.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Unterstützt PDU-Multiplexing.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU (z. B. für Transportprotokolle).</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>IPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Gruppierung von IPdus; referenziert <code>+iPdu 0..<em></code> $\\rightarrow$ <code>IPdu</code> und aggregiert hierarchisch <code>+containedIPduGroups 0..</em></code>.</li>\n<li>Assoziiert mit <code>EcuInstance</code> (<code>+associatedIPduGroup *</code>).</li>\n<li><strong><code>EcuInstance</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Repräsentiert das Steuergerät im Netzwerk.</li>\n<li><strong><code>PdurIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>PDU-Router-spezifische PDU-Gruppe; assoziiert mit <code>IPduTriggering</code> über <code>+associatedPdurIPduGroup *</code>.</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Physischer Buskanal; aggregiert per Komposition (<code>«splitable»</code>):</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+iPduTriggering 0..*</code> $\\rightarrow$ <code>IPduTriggering</code>.</li>\n<li><code>+frameTriggerings 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Frame auf dem Bus; enthält via Komposition <code>+pduToFrameMapping 0..*</code> $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Abbildung einer <code>Pdu</code> (<code>+pdu 1</code>) in einen <code>Frame</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Auslöser/Schedule für Frames; referenziert <code>+frame 1</code> $\\rightarrow$ <code>Frame</code> (<code>1..<em></code> an <code>FrameTriggering</code>) und ist mit <code>IPduTriggering</code> (<code>+iPduTriggering 0..</em></code>) verknüpft.</li>\n<li><strong><code>IPduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code> (<code>1..<em></code> an <code>IPduTriggering</code>) und verbindet <code>ISignalTriggering</code> (<code>+iSignalTriggering 0..</em></code>).</li>\n<li>Assoziiert mit <code>IPduTiming</code> (<code>+iPduTimingSpecification 0..1</code>).</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung einzelner Signale; referenziert <code>+signal 1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..*</code> an <code>ISignalTriggering</code>).</li>\n<li><strong><code>IPduTiming</code></strong>:</li>\n<li>Timing-Vorgaben für PDUs; Assoziation <code>+iPdu 0..*</code> $\\rightarrow$ <code>IPdu</code> und <code>+timingRequirement 0..1</code> $\\rightarrow$ <code>IPduTriggering</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-63535120b0d3cb20", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code> (<code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> (<code>1..<em></code> an <code>ISignalGroup</code>) und aggregiert <code>+iSignal 0..</em></code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..<em></code> am Mapping) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> am Mapping).</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>XcpPdu</code></strong>: Universal Measurement and Calibration Protocol PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code> (<code>0..1</code>).</li>\n<li><strong><code>IPduTiming</code></strong>:</li>\n<li>Timing-Spezifikation; über Komposition <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>) in <code>ISignalIPdu</code> verankert.</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Physischer Buskanal; aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+pduTriggering 0..*</code> $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><code>+frameTriggering 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Bus-Frame; aggregiert per Komposition <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, «atpPrototype»)</em>:</li>\n<li>Abbildung einer <code>Pdu</code> (<code>+pdu 1</code>, <code>1..*</code> an Mapping) in einen <code>Frame</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Frames; referenziert <code>+frame 1</code> (<code>1..<em></code> an <code>FrameTriggering</code>) und verbindet <code>+pduTriggering 0..</em></code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code> und verbindet <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Signalen und Signalgruppen; assoziiert mit <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>0..<em></code> an <code>ISignalTriggering</code>) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> an <code>ISignalTriggering</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-9e25a541c980a943", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code> (<code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> (<code>1..<em></code> an <code>ISignalGroup</code>) und aggregiert <code>+iSignal 0..</em></code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..<em></code> am Mapping) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> am Mapping).</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>XcpPdu</code></strong>: Universal Measurement and Calibration Protocol PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code> (<code>0..1</code>).</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation; über Komposition <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>) in <code>ISignalIPdu</code> verankert.</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Physischer Buskanal; aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+pduTriggering 0..*</code> $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><code>+frameTriggering 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Bus-Frame; aggregiert per Komposition <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, «atpPrototype»)</em>:</li>\n<li>Abbildung einer <code>Pdu</code> (<code>+pdu 1</code>, <code>1..*</code> an Mapping) in einen <code>Frame</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Frames; referenziert <code>+frame 1</code> (<code>1..<em></code> an <code>FrameTriggering</code>) und verbindet <code>+pduTriggering 0..</em></code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code> und verbindet <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Signalen und Signalgruppen; assoziiert mit <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>0..<em></code> an <code>ISignalTriggering</code>) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> an <code>ISignalTriggering</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-e1d79380343c08e6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code> (<code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> (<code>1..<em></code> an <code>ISignalGroup</code>) und aggregiert <code>+iSignal 0..</em></code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..<em></code> am Mapping) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> am Mapping).</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>XcpPdu</code></strong>: Universal Measurement and Calibration Protocol PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code> (<code>0..1</code>).</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation; über Komposition <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>) in <code>ISignalIPdu</code> verankert.</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Physischer Buskanal; aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+pduTriggering 0..*</code> $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><code>+frameTriggering 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Bus-Frame; aggregiert per Komposition <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, «atpPrototype»)</em>:</li>\n<li>Abbildung einer <code>Pdu</code> (<code>+pdu 1</code>, <code>1..*</code> an Mapping) in einen <code>Frame</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Frames; referenziert <code>+frame 1</code> (<code>1..<em></code> an <code>FrameTriggering</code>) und verbindet <code>+pduTriggering 0..</em></code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code> und verbindet <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Signalen und Signalgruppen; assoziiert mit <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>0..<em></code> an <code>ISignalTriggering</code>) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> an <code>ISignalTriggering</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-044b0dac567770dc", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code> (<code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> (<code>1..<em></code> an <code>ISignalGroup</code>) und aggregiert <code>+iSignal 0..</em></code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..<em></code> am Mapping) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> am Mapping).</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>XcpPdu</code></strong>: Universal Measurement and Calibration Protocol PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code> (<code>0..1</code>).</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation; über Komposition <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>) in <code>ISignalIPdu</code> verankert.</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Physischer Buskanal; aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+pduTriggering 0..*</code> $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><code>+frameTriggering 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Bus-Frame; aggregiert per Komposition <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, «atpPrototype»)</em>:</li>\n<li>Abbildung einer <code>Pdu</code> (<code>+pdu 1</code>, <code>1..*</code> an Mapping) in einen <code>Frame</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Frames; referenziert <code>+frame 1</code> (<code>1..<em></code> an <code>FrameTriggering</code>) und verbindet <code>+pduTriggering 0..</em></code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code> und verbindet <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Signalen und Signalgruppen; assoziiert mit <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>0..<em></code> an <code>ISignalTriggering</code>) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> an <code>ISignalTriggering</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-18ae1d2ff862b7df", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code> (<code>1..*</code> an <code>ISignal</code>).</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> (<code>1..<em></code> an <code>ISignalGroup</code>) und aggregiert <code>+iSignal 0..</em></code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>1..<em></code> am Mapping) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> am Mapping).</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>XcpPdu</code></strong>: Universal Measurement and Calibration Protocol PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code> (<code>0..1</code>).</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation; über Komposition <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>) in <code>ISignalIPdu</code> verankert.</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Physischer Buskanal; aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):</li>\n<li><code>+iSignalTriggering 0..*</code> $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><code>+pduTriggering 0..*</code> $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><code>+frameTriggering 0..*</code> $\\rightarrow$ <code>FrameTriggering</code>.</li>\n<li>Reflexive Assoziation: <code>+managedPhysicalChannel 0..*</code> $\\rightarrow$ <code>PhysicalChannel</code> (zur Modellierung verwalteter/untergeordneter physischer Kanäle).</li>\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Bus-Frame; aggregiert per Komposition <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, «atpPrototype»)</em>:</li>\n<li>Abbildung einer <code>Pdu</code> (<code>+pdu 1</code>) in einen <code>Frame</code>.</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Frames; referenziert <code>+frame 1</code> (<code>1..<em></code> an <code>FrameTriggering</code>) und verbindet <code>+pduTriggering 0..</em></code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>PduTriggering</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code> und verbindet <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>) $\\rightarrow$ <code>ISignalTriggering</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Triggerung von Signalen und Signalgruppen; assoziiert mit <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> (<code>0..<em></code> an <code>ISignalTriggering</code>) und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code> (<code>0..</em></code> an <code>ISignalTriggering</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-613ac92a5da84dcf", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> und aggregiert <code>+iSignal 0..*</code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code>.</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation für PDUs; aggregiert durch <code>ISignalIPdu</code> via <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Busrahmen; aggregiert <code>+pduToFrameMapping 0..*</code> $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Abbildung von PDUs auf Frames; referenziert <code>+pdu 1</code> $\\rightarrow$ <code>Pdu</code> bzw. <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code>.</li>\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Kommunikationskanal eines Netzwerks; aggregiert <code>+iSignalTriggering 0..<em></code> (<code>«atpVariation,atpSplitable»</code>), <code>+pduTriggering 0..</em></code> (<code>«atpVariation,atpSplitable»</code>) und <code>+frameTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Rekursive Assoziation: <code>+managedPhysicalChannel 0..*</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Signale; referenziert <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>ISignalIPdu</code> und aggregiert <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>).</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Frames; referenziert <code>+frame 1</code> $\\rightarrow$ <code>Frame</code> und aggregiert <code>+pduTriggering 0..*</code> (<code>«atpVariation»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-c908aa267b3d7921", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code> (Release-Stand AUTOSAR Classic R4.0.3).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Direkte Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e ohne Zwischenabstraktion.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit vollständiger Unterstützung von AUTOSAR-Variabilität (<code>«atpVariation»</code>) und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Vollständige, variabilitätsfähige Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Multibus-Architekturen als Basis für Generatoren von Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> und aggregiert <code>+iSignal 0..*</code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code>.</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation für PDUs; aggregiert durch <code>ISignalIPdu</code> via <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation»</code>).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Busrahmen; aggregiert <code>+pduToFrameMapping 0..*</code> $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Abbildung von PDUs auf Frames; referenziert <code>+pdu 1</code> $\\rightarrow$ <code>Pdu</code> bzw. <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code>.</li>\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Kommunikationskanal eines Netzwerks; aggregiert <code>+iSignalTriggering 0..<em></code> (<code>«atpVariation,atpSplitable»</code>), <code>+pduTriggering 0..</em></code> (<code>«atpVariation,atpSplitable»</code>) und <code>+frameTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Rekursive Assoziation: <code>+managedPhysicalChannel 0..*</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Signale; referenziert <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>ISignalIPdu</code> und aggregiert <code>+iSignalTriggering 0..*</code> (<code>«atpVariation»</code>).</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Frames; referenziert <code>+frame 1</code> $\\rightarrow$ <code>Frame</code> und aggregiert <code>+pduTriggering 0..*</code> (<code>«atpVariation»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfigurationsgenerierung (Com, PduR, CanIf/FrIf, CanNm):</strong></li>\n<li>Parameter wie <code>comProcessingPeriod</code> definieren direkt die zyklische Task-Periode für <code>Com_MainFunctionTx()</code> / <code>Com_MainFunctionRx()</code>.</li>\n<li><code>unusedBitPattern</code> (z. B. <code>0xFF</code> oder <code>0xAA</code>) wird von COM-Generatoren in die Initialisierungs-Buffer eincodiert, um deterministisches Busverhalten zu gewährleisten.</li>\n<li><strong>Endianness- und Alignment-Fallen:</strong></li>\n<li><code>packingByteOrder</code>: Bei <code>LEAST-SIGNIFICANT-BYTE-FIRST</code> (Intel) vs. <code>MOST-SIGNIFICANT-BYTE-FIRST</code> (Motorola) muss die Adressierung von <code>startPosition</code> exakt dem AUTOSAR-Bitnummerierungsschema (Bit 0 = LSB vs. MSB) entsprechen; Diskrepanzen führen zu Signal-Korruption beim Byte-Packing.</li>\n<li><strong>Update-Bit-Verarbeitung:</strong></li>\n<li>Wenn <code>updateIndicationBitPosition</code> gesetzt ist, generiert COM senderseitig das Setzen des Bits vor dem Senden und empfängerseitig die Prüfung. Fehlt das Bit beim Empfang, wird der Wert vom COM-Stack verworfen und kein RTE-Indication-Callback ausgelöst.</li>\n<li><strong>Filterung & Mindestverzögerung (<code>minimumDelay</code>):</strong></li>\n<li>Schützt den Bus vor Überlast bei Burst-Ereignissen (<code>transferProperty: TRIGGERED</code>). Der Generator konfiguriert den Parameter <code>ComMinimumDelayFactor</code>.</li>\n<li><strong>Splitable-Metaklassen (<code>«splitable»</code>):</strong></li>\n<li>Die Kompositionen von <code>PhysicalChannel</code> zu <code>ISignalTriggering</code>, <code>IPduTriggering</code> und <code>FrameTriggering</code> sind <code>«splitable»</code>. Das bedeutet für Tool-Entwickler: Diese Zuordnungen können auf mehrere ARXML-Dateien aufgeteilt sein (z. B. System-Description vs. ECU-Extract), ohne die Gültigkeit des Metamodells zu verletzen.</li>\n</ul>"}, {"id": "FIG-dcf23a9b0325fa8a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code>.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit durchgängiger AUTOSAR-Variabilität und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Variabilitätsfähige und modular splittbare Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 1</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 1</code> $\\rightarrow$ <code>SystemSignalGroup</code> und aggregiert <code>+iSignal 0..*</code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation,atpSplitable»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code>.</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation für PDUs; aggregiert durch <code>ISignalIPdu</code> via <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Busrahmen; aggregiert <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Abbildung von PDUs auf Frames; referenziert <code>+pdu 1</code> $\\rightarrow$ <code>Pdu</code> bzw. <code>+iPdu 1</code> $\\rightarrow$ <code>IPdu</code>.</li>\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Kommunikationskanal eines Netzwerks; aggregiert <code>+iSignalTriggering 0..<em></code> (<code>«atpVariation,atpSplitable»</code>), <code>+pduTriggering 0..</em></code> (<code>«atpVariation,atpSplitable»</code>) und <code>+frameTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Rekursive Assoziation: <code>+managedPhysicalChannel 0..*</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Signale; referenziert <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>ISignalIPdu</code> und aggregiert <code>+iSignalTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Frames; referenziert <code>+frame 1</code> $\\rightarrow$ <code>Frame</code> und aggregiert <code>+pduTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>System-Design & Generierung:</strong></li>\n<li>Zentraler Einstiegspunkt für die Generierung von AUTOSAR-COM-, NM- und Treiber-Konfigurationen (z. B. CanIf, LinIf, FrIf).</li>\n<li>Die Trennung zwischen logischer Signaldefinition (<code>Application Layer</code>), Signal-PDU-Zuordnung (<code>Interaction &amp; Network Layer</code>) und Bus-Mapping (<code>Data Link Layer</code>) ermöglicht eine herstellerunabhängige Wiederverwendung von Software-Komponenten.</li>\n<li><strong>Variabilität & Splitting:</strong></li>\n<li>Durchgängige Kennzeichnung zentraler Aggregationen und Referenzen mit <code>«atpVariation,atpSplitable»</code> ermöglicht die feingranulare Aufteilung und variante Konfiguration über getrennte ARXML-Dateien hinweg auf allen Abstraktionsebenen (Signal-Mapping, Timing, PDU-Gruppierung, Frame-Mapping und Bus-Triggering).</li>\n</ul>"}, {"id": "FIG-926ac53510366331", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code>.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit durchgängiger AUTOSAR-Variabilität und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Variabilitätsfähige und modular splittbare Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 0..1</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 0..1</code> $\\rightarrow$ <code>SystemSignalGroup</code> und aggregiert <code>+iSignal 0..*</code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation,atpSplitable»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code>.</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation für PDUs; aggregiert durch <code>ISignalIPdu</code> via <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Busrahmen; aggregiert <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Abbildung von PDUs auf Frames; referenziert <code>+pdu 0..1</code> $\\rightarrow$ <code>Pdu</code> bzw. <code>+iPdu 0..1</code> $\\rightarrow$ <code>IPdu</code>.</li>\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotypen <code>Identifiable</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Kommunikationskanal eines Netzwerks; aggregiert <code>+iSignalTriggering 0..<em></code> (<code>«atpVariation,atpSplitable»</code>), <code>+pduTriggering 0..</em></code> (<code>«atpVariation,atpSplitable»</code>) und <code>+frameTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Rekursive Assoziation: <code>+managedPhysicalChannel 0..*</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Signale; referenziert <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>ISignalIPdu</code> und aggregiert <code>+iSignalTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Frames; referenziert <code>+frame 0..1</code> $\\rightarrow$ <code>Frame</code> und aggregiert <code>+pduTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>System-Design & Generierung:</strong></li>\n<li>Zentraler Einstiegspunkt für die Generierung von AUTOSAR-COM-, NM- und Treiber-Konfigurationen (z. B. CanIf, LinIf, FrIf).</li>\n<li>Die Trennung zwischen logischer Signaldefinition (<code>Application Layer</code>), Signal-PDU-Zuordnung (<code>Interaction &amp; Network Layer</code>) und Bus-Mapping (<code>Data Link Layer</code>) ermöglicht eine herstellerunabhängige Wiederverwendung von Software-Komponenten.</li>\n<li><strong>Variabilität & Splitting:</strong></li>\n<li>Durchgängige Kennzeichnung zentraler Aggregationen und Referenzen mit <code>«atpVariation,atpSplitable»</code> ermöglicht die feingranulare Aufteilung und variante Konfiguration über getrennte ARXML-Dateien hinweg auf allen Abstraktionsebenen (Signal-Mapping, Timing, PDU-Gruppierung, Frame-Mapping und Bus-Triggering).</li>\n</ul>"}, {"id": "FIG-fc859947991226dc", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code>.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit durchgängiger AUTOSAR-Variabilität und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Variabilitätsfähige und modular splittbare Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 0..1</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 0..1</code> $\\rightarrow$ <code>SystemSignalGroup</code> und aggregiert <code>+iSignal 0..*</code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation,atpSplitable»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code>.</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation für PDUs; aggregiert durch <code>ISignalIPdu</code> via <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Busrahmen; aggregiert <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Abbildung von PDUs auf Frames; referenziert <code>+pdu 0..1</code> $\\rightarrow$ <code>Pdu</code> bzw. <code>+iPdu 0..1</code> $\\rightarrow$ <code>IPdu</code>.</li>\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotypen <code>Identifiable</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Kommunikationskanal eines Netzwerks; aggregiert <code>+iSignalTriggering 0..<em></code> (<code>«atpVariation,atpSplitable»</code>), <code>+pduTriggering 0..</em></code> (<code>«atpVariation,atpSplitable»</code>) und <code>+frameTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Rekursive Assoziation: <code>+managedPhysicalChannel 0..*</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Signale; referenziert <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>ISignalIPdu</code> und aggregiert <code>+iSignalTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Frames; referenziert <code>+frame 0..1</code> $\\rightarrow$ <code>Frame</code> und aggregiert <code>+pduTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>System-Design & Generierung:</strong></li>\n<li>Zentraler Einstiegspunkt für die Generierung von AUTOSAR-COM-, NM- und Treiber-Konfigurationen (z. B. CanIf, LinIf, FrIf).</li>\n<li>Die Trennung zwischen logischer Signaldefinition (<code>Application Layer</code>), Signal-PDU-Zuordnung (<code>Interaction &amp; Network Layer</code>) und Bus-Mapping (<code>Data Link Layer</code>) ermöglicht eine herstellerunabhängige Wiederverwendung von Software-Komponenten.</li>\n<li><strong>Variabilität & Splitting:</strong></li>\n<li>Durchgängige Kennzeichnung zentraler Aggregationen und Referenzen mit <code>«atpVariation,atpSplitable»</code> ermöglicht die feingranulare Aufteilung und variante Konfiguration über getrennte ARXML-Dateien hinweg auf allen Abstraktionsebenen (Signal-Mapping, Timing, PDU-Gruppierung, Frame-Mapping und Bus-Triggering).</li>\n</ul>"}, {"id": "FIG-135c76f5a86f388b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR XML mit Variabilitäts- und Splitting-Konzepten).</li>\n<li><strong>Paket / Modellbereich:</strong> <code>AUTOSAR_SystemTemplate::FibexCore::Communication</code>.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Vertikale Gliederung in drei funktionale Schichten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Application Layer:</strong> Modellierung von Anwendungssignalen (<code>SystemSignal</code>, <code>SystemSignalGroup</code>) als eigenständige <code>ARElement</code>e.</li>\n<li><strong>Interaction & Network Layer:</strong> PDU- und Signal-Abstraktion (COM-Stack, NM, DCM, XCP; Signal- und Signalgruppen-Mapping, strukturierte PDU-Typen, <code>ISignalIPduGroup</code>).</li>\n<li><strong>Data Link Layer:</strong> Physische Busabstraktion (<code>Frame</code>, <code>PhysicalChannel</code>) mit durchgängiger AUTOSAR-Variabilität und Splitting (<code>«atpVariation,atpSplitable»</code>) auf Triggering- und Mapping-Ebene.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Funktionaler Zweck:</strong> Variabilitätsfähige und modular splittbare Beschreibung der Signal- und PDU-Kapselung sowie des Bus-Routings für Kommunikations- und Transportprotokoll-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Enthaltene Klassen</p>\n<p class=\"fig-p\">##### A. Application Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>SystemSignal</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Anwendungsbezogenes Einzelsignal.</li>\n<li><strong><code>SystemSignalGroup</code></strong> <em>(Stereotyp <code>ARElement</code>)</em>:</li>\n<li>Gruppierung logisch zusammengehöriger Signale; Aggregation: <code>+systemSignal *</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n</ul>\n<p class=\"fig-p\">##### B. Interaction & Network Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>ISignal</code></strong> <em>(Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Interaction-Layer-Signal; referenziert <code>+systemSignal 0..1</code> $\\rightarrow$ <code>SystemSignal</code>.</li>\n<li><strong><code>ISignalGroup</code></strong> <em>(Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Interaction-Layer-Signalgruppe; referenziert <code>+systemSignalGroup 0..1</code> $\\rightarrow$ <code>SystemSignalGroup</code> und aggregiert <code>+iSignal 0..*</code> $\\rightarrow$ <code>ISignal</code>.</li>\n<li><strong><code>ISignalToIPduMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Mapping von Einzelsignalen oder Signalgruppen in PDUs.</li>\n<li>Assoziationen: <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li>Kompositionen:</li>\n<li>Enthalten in <code>ISignalIPdu</code> via <code>+iSignalToPduMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Enthalten in <code>NmPdu</code> via <code>+iSignalToIPduMapping 0..*</code>.</li>\n<li><strong><code>Pdu</code></strong> <em>(abstrakte Basisklasse, Stereotypen <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Generische Protocol Data Unit.</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>NmPdu</code></strong>: Netzwerkmanagement-PDU.</li>\n<li><strong><code>GeneralPurposePdu</code></strong>: Generische PDU für allgemeine Transportzwecke.</li>\n<li><strong><code>IPdu</code></strong>: Interaktions-PDU.</li>\n<li><strong><code>UserDefinedPdu</code></strong>: Nutzerdefinierte generische PDU.</li>\n<li><strong><code>IPdu</code></strong> <em>(Spezialisierung von <code>Pdu</code>)</em>:</li>\n<li>Spezialisierungen:</li>\n<li><strong><code>ISignalIPdu</code></strong>: Träger von <code>ISignalToIPduMapping</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>DcmIPdu</code></strong>: Diagnose-PDU.</li>\n<li><strong><code>J1939DcmIPdu</code></strong>: Diagnose-PDU nach SAE J1939.</li>\n<li><strong><code>GeneralPurposeIPdu</code></strong>: Generische Interaktions-PDU.</li>\n<li><strong><code>MultiplexedIPdu</code></strong>: Gemultiplextes PDU-Format.</li>\n<li><strong><code>NPdu</code></strong>: Netzwerk-PDU.</li>\n<li><strong><code>UserDefinedIPdu</code></strong>: Nutzerdefinierte Interaktions-PDU.</li>\n<li><strong><code>ISignalIPduGroup</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Verwaltung von Signalgruppen-PDUs; referenziert <code>+iSignalIPdu 0..<em></code> (<code>«atpVariation,atpSplitable»</code>) und aggregiert hierarchisch <code>+containedISignalIPduGroup 0..</em></code>.</li>\n<li><strong><code>IPduTiming</code></strong> <em>(Stereotyp <code>Describable</code>)</em>:</li>\n<li>Timing-Spezifikation für PDUs; aggregiert durch <code>ISignalIPdu</code> via <code>+iPduTimingSpecification 0..1</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<p class=\"fig-p\">##### C. Data Link Layer</p>\n<ul class=\"fig-list\">\n<li><strong><code>Frame</code></strong> <em>(Stereotyp <code>FibexElement</code>)</em>:</li>\n<li>Physischer Busrahmen; aggregiert <code>+pduToFrameMapping 0..*</code> (<code>«atpVariation,atpSplitable»</code>) $\\rightarrow$ <code>PduToFrameMapping</code>.</li>\n<li><strong><code>PduToFrameMapping</code></strong> <em>(Stereotyp <code>Identifiable</code>, <code>«atpPrototype»</code>)</em>:</li>\n<li>Abbildung von PDUs auf Frames; referenziert <code>+pdu 0..1</code> $\\rightarrow$ <code>Pdu</code> bzw. <code>+iPdu 0..1</code> $\\rightarrow$ <code>IPdu</code>.</li>\n<li><strong><code>PhysicalChannel</code></strong> <em>(Stereotypen <code>Identifiable</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em>:</li>\n<li>Kommunikationskanal eines Netzwerks; aggregiert <code>+iSignalTriggering 0..<em></code> (<code>«atpVariation,atpSplitable»</code>), <code>+pduTriggering 0..</em></code> (<code>«atpVariation,atpSplitable»</code>) und <code>+frameTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Rekursive Assoziation: <code>+managedPhysicalChannel 0..*</code>.</li>\n<li><strong><code>ISignalTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Signale; referenziert <code>+iSignal 0..1</code> $\\rightarrow$ <code>ISignal</code> und <code>+iSignalGroup 0..1</code> $\\rightarrow$ <code>ISignalGroup</code>.</li>\n<li><strong><code>PduTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für PDUs; referenziert <code>+iPdu 1</code> $\\rightarrow$ <code>ISignalIPdu</code> und aggregiert <code>+iSignalTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n<li><strong><code>FrameTriggering</code></strong> <em>(Stereotyp <code>Identifiable</code>)</em>:</li>\n<li>Bus-Triggering für Frames; referenziert <code>+frame 0..1</code> $\\rightarrow$ <code>Frame</code> und aggregiert <code>+pduTriggering 0..*</code> (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Konfigurationsbasis für folgende Laufzeit-Sequenzen im AUTOSAR BSW-Stack:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[SW-C / RTE]</p>\n<p class=\"fig-p\">│ (Write SystemSignal / SystemSignalGroup)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR COM]</p>\n<p class=\"fig-p\">│ 1. ISignalToIPduMapping: Packing in SignalIPdu (Startpos, Endianness)</p>\n<p class=\"fig-p\">│ 2. Setzen von updateIndicationBitPosition</p>\n<p class=\"fig-p\">│ 3. Auswertung TransferProperty (TRIGGERED -> Sendeanforderung; PENDING -> Warten auf Zyklus)</p>\n<p class=\"fig-p\">│ 4. Validierung IPduTiming (minimumDelay Prüfen / MinDelayTimer)</p>\n<p class=\"fig-p\">│ 5. PduR_ComTransmit(SignalIPduId)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[PDU Router (PduR)]</p>\n<p class=\"fig-p\">│ 6. Routing der IPdu zu Interface-Modul (z. B. CanIf, FrIf, LinIf)</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Bus Interface / Driver (CanIf / FlexRay)]</p>\n<p class=\"fig-p\">│ 7. PduToFrameMapping / FrameTriggering: Zusammenbau des Frame-Payloads</p>\n<p class=\"fig-p\">│ 8. Zuordnung zu Mailbox / Hardware Transmit Handle via PhysicalChannel-Konfiguration</p>\n<p class=\"fig-p\">│ 9. Physikalische Bus-Transmission</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Dynamische Steuerung über <code>IPduGroup</code>:</strong></li>\n<li>Start/Stopp von Kommunikationspfaden zur Laufzeit über <code>Com_IpduGroupStart()</code> bzw. <code>Com_IpduGroupStop()</code>, gesteuert durch den <code>ComM</code> (Communication Manager) anhand des Netzwerkzustands (Full Comm / Silent / No Comm).</li>\n<li><strong>Multiplexing-Pfad (<code>MultiplexedIPdu</code>):</strong></li>\n<li><code>selectorFieldStartPosition</code> bestimmt das dynamische Switch-Feld. Je nach Wert werden alternative Signallayouts in denselben PDU-Payload gemappt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>System-Design & Generierung:</strong></li>\n<li>Zentraler Einstiegspunkt für die Generierung von AUTOSAR-COM-, NM- und Treiber-Konfigurationen (z. B. CanIf, LinIf, FrIf).</li>\n<li>Die Trennung zwischen logischer Signaldefinition (<code>Application Layer</code>), Signal-PDU-Zuordnung (<code>Interaction &amp; Network Layer</code>) und Bus-Mapping (<code>Data Link Layer</code>) ermöglicht eine herstellerunabhängige Wiederverwendung von Software-Komponenten.</li>\n<li><strong>Variabilität & Splitting:</strong></li>\n<li>Durchgängige Kennzeichnung zentraler Aggregationen und Referenzen mit <code>«atpVariation,atpSplitable»</code> ermöglicht die feingranulare Aufteilung und variante Konfiguration über getrennte ARXML-Dateien hinweg auf allen Abstraktionsebenen (Signal-Mapping, Timing, PDU-Gruppierung, Frame-Mapping und Bus-Triggering).</li>\n</ul>"}], "trans": [{"from": "FIG-b645eab3aee47ea8", "to": "FIG-f8c73236c26d0564", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Sämtliche Attribute in allen Klassen (<code>length</code>, <code>startPosition</code>, <code>packingByteOrder</code>, <code>transferProperty</code>, <code>updateIndicationBitPosition</code>, <code>selectorField*</code>, <code>comConfigurationId</code>, etc.) wurden aus der Diagrammdarstellung ausgeblendet.</li>\n<li>Ergänzung der Spezialisierungen von <code>Pdu</code>: <code>UserDefinedPdu</code>.</li>\n<li>Ergänzung der Spezialisierungen von <code>IPdu</code>: <code>UserDefinedIPdu</code>.</li>\n<li>Ergänzung der Klasse <code>PdurIPduGroup</code> (Spezialisierung/Typ mit Assoziation <code>+associatedPdurIPduGroup *</code> zu <code>IPduTriggering</code>).</li>\n<li>Assoziation von <code>ISignalToIPduMapping</code> zu <code>NmPdu</code> (<code>+iSignalToIPduMapping 0..*</code>) hinzugefügt.</li>\n<li>Kardinalitäts- und Rollenanpassung bei <code>IPduTiming</code>: Multiplizität zu <code>IPduTriggering</code> nun explizit als Assoziationsrolle <code>+iPduTimingSpecification 0..1</code> dargestellt; Assoziationsrolle zu <code>IPdu</code> lautet nun <code>+iPdu 0..<em></code> (vorher <code>1..</em></code>).</li>\n<li>Umbenennung des Namensraum-Präfixes bei <code>CoreTopology::EcuInstance</code> und <code>CoreTopology::PhysicalChannel</code> zu <code>EcuInstance</code> und <code>PhysicalChannel</code>.</li>\n<li>Entfernung des Stereotyps <code>«atpPrototype»</code> an <code>PduToFrameMapping</code>.</li>\n<li>Entfernung des Stereotyps <code>«splitable»</code> an der Komposition von <code>ISignalTriggering</code> auf <code>PhysicalChannel</code>.</li>\n</ul>"}, {"from": "FIG-f8c73236c26d0564", "to": "FIG-63535120b0d3cb20", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Wegfall der Klassen <code>AbstractSignal</code>, <code>EcuInstance</code>, <code>IPduGroup</code> und <code>PdurIPduGroup</code>.</li>\n<li><code>SystemSignal</code> und <code>SystemSignalGroup</code> sind nun direkt als <code>ARElement</code> modelliert; direkte Assoziation <code>+systemSignal *</code> von <code>SystemSignalGroup</code> auf <code>SystemSignal</code>.</li>\n<li>Ergänzung von <code>ISignalGroup</code> (<code>FibexElement</code>) im Interaction & Network Layer mit Assoziation <code>+systemSignalGroup 1</code> zu <code>SystemSignalGroup</code> und Aggregation/Beziehung <code>+iSignal 0..*</code> zu <code>ISignal</code>.</li>\n<li>Umbenennung von <code>SignalIPdu</code> zu <code>ISignalIPdu</code> und <code>IPduGroup</code> zu <code>ISignalIPduGroup</code> (<code>FibexElement</code>).</li>\n<li>Ergänzung von <code>XcpPdu</code> als Spezialisierung von <code>Pdu</code>.</li>\n<li>Umbenennung von <code>IPduTriggering</code> zu <code>PduTriggering</code>.</li>\n<li>Hinzufügen von AUTOSAR-Variabilitäts- und Splitting-Stereotypen: <code>«atpVariation,atpSplitable»</code> an <code>PhysicalChannel</code>-Kompositionen (<code>+frameTriggering 0..<em></code>, <code>+pduTriggering 0..</em></code>, <code>+iSignalTriggering 0..*</code>), <code>«atpVariation»</code> an <code>+iSignalToPduMapping</code>, <code>+iPduTimingSpecification</code>, <code>+iSignalIPdu</code>, <code>+pduToFrameMapping</code> sowie Triggering-Referenzen.</li>\n<li>Wiederaufnahme des Stereotyps <code>«atpPrototype»</code> an <code>PduToFrameMapping</code>.</li>\n<li>Anpassung von Rollennamen und Multiplizitäten: <code>+frameTriggerings 0..<em></code> zu <code>+frameTriggering 0..</em></code>, Mapping-Beziehungen zwischen <code>ISignalToIPduMapping</code> und <code>ISignalGroup</code>/<code>ISignal</code> via <code>+iSignalGroup 0..1</code> und <code>+iSignal 0..1</code>.</li>\n</ul>"}, {"from": "FIG-63535120b0d3cb20", "to": "FIG-9e25a541c980a943", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der Klassen <code>GeneralPurposePdu</code> (Spezialisierung von <code>Pdu</code>) und <code>GeneralPurposeIPdu</code> (Spezialisierung von <code>IPdu</code>).</li>\n<li>Ergänzung der Klasse <code>J1939DcmIPdu</code> (Spezialisierung von <code>IPdu</code>).</li>\n<li><code>IPduTiming</code> erhält den Stereotyp <code>«Describable»</code> (vorher ohne Stereotyp dargestellt).</li>\n</ul>"}, {"from": "FIG-9e25a541c980a943", "to": "FIG-e1d79380343c08e6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Grafische Bereinigung des Klassenkästchens <code>DcmIPdu</code>: Das versehentlich im selben Headerblock platzierte Label <code>XcpPdu</code> wurde entfernt; die Klassen <code>XcpPdu</code> und <code>DcmIPdu</code> sind wieder als separate Boxen dargestellt.</li>\n<li>Layout-Kompaktierung und Textpositionierungs-Korrektur bei der Multiplizität <code>0..1</code> an der Assoziation <code>+iSignalGroup</code> zu <code>ISignalToIPduMapping</code>.</li>\n</ul>"}, {"from": "FIG-e1d79380343c08e6", "to": "FIG-044b0dac567770dc", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entfernung der redundanten Multiplizitätsangabe <code>1..*</code> an der Referenzlinie von <code>PduTriggering</code> zu <code>IPdu</code>.</li>\n<li>Leichte Anpassung der Textplatzierung des Multiplizitätslabels <code>0..1</code> bei <code>+iSignalGroup</code>.</li>\n</ul>"}, {"from": "FIG-044b0dac567770dc", "to": "FIG-18ae1d2ff862b7df", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der reflexiven Assoziation <code>+managedPhysicalChannel 0..*</code> an der Klasse <code>PhysicalChannel</code>.</li>\n</ul>"}, {"from": "FIG-18ae1d2ff862b7df", "to": "FIG-613ac92a5da84dcf", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Korrektur der Textplatzierung und Trennung am Mapping-Ende der Assoziation zwischen <code>ISignalToIPduMapping</code> und <code>ISignalGroup</code> (Aufspaltung/Präzisierung der Beschriftung).</li>\n<li>Korrektur eines Tippfehlers / Leerzeichens bei der Rolle <code>+iSignalToPduMapping 0..*</code>.</li>\n<li>Entfernung des redundanten/irrtümlichen Stereotyps <code>«atpVariation»</code> an der Aggregation <code>+pduToFrameMapping 0..*</code> von <code>Frame</code> zu <code>PduToFrameMapping</code> (bereits durch <code>«atpPrototype»</code> bzw. Kontext modelliert).</li>\n</ul>"}, {"from": "FIG-613ac92a5da84dcf", "to": "FIG-c908aa267b3d7921", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bereinigung der Textüberlappung / Darstellung bei der Beschriftung <code>+iSignalGroup 0..1</code> bzw. <code>0..* «atpVariation»</code>.</li>\n</ul>"}, {"from": "FIG-c908aa267b3d7921", "to": "FIG-dcf23a9b0325fa8a", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Erweiterung der Variabilitätskonzepte von einfacher Variabilität (<code>«atpVariation»</code>) auf Variabilität mit Splitting (<code>«atpVariation,atpSplitable»</code>) an mehreren Modellelementen:</li>\n<li><code>ISignalIPdu</code> $\\rightarrow$ <code>ISignalToIPduMapping</code> (<code>+iSignalToPduMapping 0..*</code>)</li>\n<li><code>ISignalIPdu</code> $\\rightarrow$ <code>IPduTiming</code> (<code>+iPduTimingSpecification 0..1</code>)</li>\n<li><code>ISignalIPduGroup</code> $\\rightarrow$ <code>ISignalIPdu</code> (<code>+iSignalIPdu 0..*</code>)</li>\n<li><code>Frame</code> $\\rightarrow$ <code>PduToFrameMapping</code> (<code>+pduToFrameMapping 0..*</code>)</li>\n<li><code>PduTriggering</code> $\\rightarrow$ <code>ISignalTriggering</code> (<code>+iSignalTriggering 0..*</code>)</li>\n<li><code>FrameTriggering</code> $\\rightarrow$ <code>PduTriggering</code> (<code>+pduTriggering 0..*</code>)</li>\n<li>Grafische Bereinigung und Vergrößerung des Diagrammlayouts.</li>\n</ul>"}, {"from": "FIG-dcf23a9b0325fa8a", "to": "FIG-926ac53510366331", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Hinzufügen des Stereotyps <code>UploadableDesignElement</code> zu den Klassen <code>ISignal</code>, <code>ISignalGroup</code>, <code>Pdu</code> und <code>PhysicalChannel</code>.</li>\n<li>Änderung der Ziel-Kardinalitäten von Pflichtreferenzen (<code>1</code>) zu optionalen Referenzen (<code>0..1</code>):</li>\n<li><code>ISignal</code> $\\rightarrow$ <code>SystemSignal</code> (<code>+systemSignal</code>: von <code>1</code> auf <code>0..1</code>)</li>\n<li><code>ISignalGroup</code> $\\rightarrow$ <code>SystemSignalGroup</code> (<code>+systemSignalGroup</code>: von <code>1</code> auf <code>0..1</code>)</li>\n<li><code>PduToFrameMapping</code> $\\rightarrow$ <code>IPdu</code> (<code>+iPdu</code>: von <code>1</code> auf <code>0..1</code>)</li>\n<li><code>PduToFrameMapping</code> $\\rightarrow$ <code>Pdu</code> (<code>+pdu</code>: von <code>1</code> auf <code>0..1</code>)</li>\n<li><code>FrameTriggering</code> $\\rightarrow$ <code>Frame</code> (<code>+frame</code>: von <code>1</code> auf <code>0..1</code>)</li>\n</ul>"}, {"from": "FIG-926ac53510366331", "to": "FIG-fc859947991226dc", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bereinigung eines Render-Artefakts / Textüberlappung bei der Assoziationsbeschriftung <code>+iSignal 0..1</code> zwischen <code>ISignalToIPduMapping</code> und <code>ISignal</code>.</li>\n</ul>"}, {"from": "FIG-fc859947991226dc", "to": "FIG-135c76f5a86f388b", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
